<template><div class="page"><div class="page-head"><div><h1 class="page-title">借阅流通</h1><div class="page-sub">办理借书、归还和续借业务</div></div><el-button type="primary" @click="visible=true"><el-icon><Promotion/></el-icon>办理借阅</el-button></div><div class="toolbar"><el-input v-model="keyword" placeholder="搜索图书、读者编号或姓名" style="width:330px" clearable @keyup.enter="load"/><el-button type="primary" plain @click="load">查询</el-button><el-select v-model="status" placeholder="借阅状态" clearable style="width:150px"><el-option label="借阅中" value="BORROWED"/><el-option label="逾期未还" value="OVERDUE"/><el-option label="已归还" value="RETURNED"/><el-option label="逾期归还" value="OVERDUE_RETURNED"/></el-select></div><el-card class="table-card"><el-table :data="filtered"><el-table-column prop="readerNo" label="读者编号"/><el-table-column prop="realName" label="读者姓名"/><el-table-column prop="title" label="图书名称" min-width="180"/><el-table-column prop="barcode" label="馆藏条码"/><el-table-column prop="borrowTime" label="借阅时间" width="170"/><el-table-column prop="dueTime" label="应还时间" width="170"/><el-table-column label="状态"><template #default="{row}"><el-tag :type="statusType(row)">{{statusText(row)}}</el-tag></template></el-table-column><el-table-column label="操作" width="150"><template #default="{row}"><template v-if="row.status==='BORROWED'"><el-button link type="primary" @click="renew(row)">续借</el-button><el-button link type="success" @click="back(row)">归还</el-button></template><span v-else class="muted">已完成</span></template></el-table-column></el-table><div class="pagination"><el-pagination background layout="total,prev,pager,next" :total="total" v-model:current-page="page" @current-change="load"/></div></el-card><el-dialog v-model="visible" title="办理图书借阅" width="480"><el-alert title="请扫描馆藏条码，并确认读者借阅资格" type="info" :closable="false" show-icon/><el-form label-position="top" style="margin-top:18px"><el-form-item label="读者ID"><el-input-number v-model="form.readerId" :min="1" style="width:100%"/></el-form-item><el-form-item label="馆藏条码"><el-input v-model="form.barcode" placeholder="例如 BK000002"><template #prefix><el-icon><Postcard/></el-icon></template></el-input></el-form-item></el-form><template #footer><el-button @click="visible=false">取消</el-button><el-button type="primary" @click="borrow">确认借阅</el-button></template></el-dialog></div></template><script setup lang="ts">import{ref,reactive,onMounted,computed}from'vue';import api from'../api';import{ElMessage,ElMessageBox}from'element-plus';const rows=ref<any[]>([]),total=ref(0),page=ref(1),keyword=ref(''),status=ref(''),visible=ref(false),form=reactive({readerId:1,barcode:'BK000002',operatorId:1});const filtered=computed(()=>status.value?rows.value.filter(x=>displayStatus(x)===status.value):rows.value);onMounted(load);async function load(){const r:any=await api.get('/api/borrows',{params:{page:page.value,size:10,keyword:keyword.value}});rows.value=r.records;total.value=r.total}function displayStatus(row:any){return row.status==='BORROWED'&&new Date(row.dueTime)<new Date()?'OVERDUE':row.status}function statusText(row:any){const s=displayStatus(row);return({BORROWED:'借阅中',OVERDUE:'逾期未还',RETURNED:'已归还',OVERDUE_RETURNED:'逾期归还'}as any)[s]||s}function statusType(row:any){return({BORROWED:'warning',OVERDUE:'danger',RETURNED:'success',OVERDUE_RETURNED:'info'}as any)[displayStatus(row)]||'info'}async function borrow(){await api.post('/api/borrows',form);ElMessage.success('借阅办理成功');visible.value=false;load()}async function renew(r:any){await ElMessageBox.confirm(`确定为《${r.title}》续借15天吗？`,'续借确认');await api.put(`/api/borrows/${r.id}/renew`);ElMessage.success('续借成功');load()}async function back(r:any){await ElMessageBox.confirm(`确认归还《${r.title}》吗？`,'归还确认');await api.put(`/api/borrows/${r.id}/return`);ElMessage.success('归还成功');load()}</script>

